/**
 * Renders a Bot as one Agent Skill folder (https://agentskills.io), the format that Claude Code,
 * Codex, Cursor, Gemini CLI, OpenCode, GitHub Copilot and Grok all load:
 *
 *   SKILL.md             who the bot is, its instructions, and an index of the files below
 *   skills/<slug>.md     one playbook per Grok Bot skill
 *   routines/<slug>.md   one prompt per Grok Bot routine
 */

import { cleanText } from './text.js';

/** The folders inside a skill folder that hold the playbook and routine files (the two OWN_FILE allows). */
export const PLAYBOOK_FOLDERS = ['skills', 'routines'];

const MAX_DESCRIPTION = 1024; // Agent Skills limit
const MAX_SUMMARY = 700; // leaves room for the "Use when" sentence

// Every file grokport writes ends with a note naming the bot it came from (a link without spaces or
// control characters, so it's safe to print). SKILL.md also lists the playbook and routine files, so an
// update removes exactly those and nothing the user added.
const NOTE = /^<!-- generated by grokport from ([^\s\x00-\x1f\x7f-\x9f]+)\. Reinstalling replaces this file\. -->$/;
const FILE_LIST = /^<!-- grokport files: (\[[^\]]*\]) -->$/;
const OWN_FILE = /^(?:skills|routines)\/[a-z0-9]+(?:-[a-z0-9]+)*\.md$/;

/**
 * @param {import('./grok/recipe.js').Bot} bot
 * @returns {Record<string, string>} relative path -> file content
 */
export function renderBundle(bot) {
  const extras = {};
  for (const skill of bot.skills) extras[`skills/${skill.slug}.md`] = withNewline(skill.content);
  for (const routine of bot.routines) extras[`routines/${routine.slug}.md`] = withNewline(routine.content);
  return { 'SKILL.md': renderSkill(bot, Object.keys(extras)), ...extras };
}

/** YAML frontmatter. Values are JSON-encoded (after oneLine), which is valid YAML. */
export function renderFrontmatter(fields) {
  const lines = Object.entries(fields).map(([key, value]) => `${key}: ${JSON.stringify(value)}`);
  return ['---', ...lines, '---'].join('\n');
}

/** One line telling an agent what the bot does and when to use it, within every agent's limits. */
export function describeBot(bot) {
  const summary = truncate(oneLine(bot.description), MAX_SUMMARY);
  const trigger = `Use when the user asks for ${bot.name} or wants help with what it does.`;
  return truncate(oneLine(`${summary} ${trigger}`), MAX_DESCRIPTION);
}

export function generatedNote(bot) {
  return `<!-- generated by grokport from ${bot.url}. Reinstalling replaces this file. -->`;
}

/**
 * What grokport recorded in a file it generated: the source bot's URL and, for SKILL.md, the bot's
 * name (its title) and the playbook and routine files it wrote. Null when grokport didn't generate
 * the file.
 *
 * Only the trailer counts (the last line, or for SKILL.md the line above its file list), so a note
 * quoted earlier in the bot's own text can't claim the file or change what gets removed. The name is
 * only for showing.
 * @returns {{ source: string, name?: string, files: string[] } | null}
 */
export function readGenerated(text) {
  const lines = String(text ?? '')
    .trimEnd()
    .split('\n')
    .map((line) => line.trim());
  const list = FILE_LIST.exec(lines.at(-1) ?? '');
  if (list) lines.pop();
  const source = NOTE.exec(lines.at(-1) ?? '')?.[1];
  if (!source) return null;

  let files;
  try {
    files = JSON.parse(list?.[1] ?? '[]');
  } catch {
    files = [];
  }
  const title = lines.find((line) => line.startsWith('# '));
  return {
    source,
    name: title ? cleanText(title.slice(2)).trim() : undefined,
    // Only ever trust names of our own playbook files, never paths that could leave the folder.
    files: files.filter((file) => typeof file === 'string' && OWN_FILE.test(file)),
  };
}

function renderSkill(bot, extraFiles) {
  const byline = bot.author ? ` by ${bot.author}` : '';
  const sections = [
    renderFrontmatter({ name: bot.slug, description: describeBot(bot) }),
    `# ${bot.name}`,
    `You are **${bot.name}**, a Grok Bot${byline} brought over from ${bot.url}. While this skill is ` +
      `active, work as ${bot.name}: follow the instructions below and read the matching playbook ` +
      "before each task. File paths are relative to this skill's folder.",
    'This bot was written for Grok Bot, which gave it a cloud computer, scheduled routines and app ' +
      "connections. When its instructions rely on something you don't have, use the closest thing " +
      "you do have (your own tools, a local folder instead of Grok Bot's workspace, running a routine " +
      "when asked) and tell the user plainly when something isn't possible here.",
  ];

  if (bot.instructions.trim()) {
    sections.push(`## Instructions\n\n${bot.instructions.trim()}`);
  }
  if (bot.starterSkill) {
    sections.push(`## First run\n\nStart by following \`skills/${bot.starterSkill}.md\`.`);
  }
  if (bot.skills.length > 0) {
    sections.push(section('Playbooks', bot.skills.map((skill) => indexEntry('skills', skill))));
  }
  if (bot.routines.length > 0) {
    sections.push(
      section(
        'Routines',
        bot.routines.map((routine) => indexEntry('routines', routine)),
        'In Grok Bot these ran on a schedule. Run one when the user asks for it.',
      ),
    );
  }

  const facts = bot.memory.filter((memory) => memory.kind !== 'log');
  if (facts.length > 0) {
    sections.push(section('What you know', facts.map((memory) => `- ${oneLine(memory.content)}`)));
  }
  if (bot.connectors.length > 0) {
    sections.push(
      section(
        'Apps',
        bot.connectors.map((app) => `- **${app.name}**${app.description ? `: ${oneLine(app.description)}` : ''}`),
        'In Grok Bot this bot was connected to these apps. Use matching tools if you have them. ' +
          "If you don't, say what is missing and carry on without them.",
      ),
    );
  }

  sections.push(`${generatedNote(bot)}\n<!-- grokport files: ${JSON.stringify(extraFiles)} -->`);
  return `${sections.join('\n\n')}\n`;
}

function section(title, lines, intro) {
  return [`## ${title}`, ...(intro ? [intro] : []), lines.join('\n')].join('\n\n');
}

function indexEntry(folder, item) {
  const description = item.description ? ` ${oneLine(item.description)}` : '';
  return `- \`${folder}/${item.slug}.md\`: **${item.name}**.${description}`;
}

/** Single line, no control characters or angle brackets: safe for frontmatter and list items. */
function oneLine(text) {
  return cleanText(text).replace(/[<>]/g, '').replace(/\s+/g, ' ').trim();
}

function truncate(text, max) {
  if (text.length <= max) return text;
  const cut = text.slice(0, max - 1);
  const lastSpace = cut.lastIndexOf(' ');
  return `${lastSpace > max / 2 ? cut.slice(0, lastSpace) : cut}…`;
}

function withNewline(text) {
  return text.endsWith('\n') ? text : `${text}\n`;
}
